const SONGS = [{"id": 0, "title": "I Am Me", "moment": "Begin", "audience": "Children", "blurb": "A little belonging. A voice of your own. A way to begin.", "use": "Introduce the final line as your shared cue: finish cleaning up, gather at the carpet, or get ready for the next activity by “Just like this… I begin.”", "quote": "All of me is welcome, every part I bring.", "color": "coral", "variants": {"English": "Chorus\n\nI am me—\nI belong.\nI have a voice—\nI am strong.\n\nI can try,\nI can grow—\nI am learning\nwho I am.\n\n⸻\n\nVerse 1\n\nSome days I feel quiet,\nsome days I feel loud,\nsome days I feel unsure,\nsome days I feel proud.\n\nAll of me is welcome,\nevery part I bring—\nI don’t have to hide it,\nI can be seen.\n\n⸻\n\nChorus\n\nI am me—\nI belong.\nI have a voice—\nI am strong.\n\nI can try,\nI can grow—\nI am learning\nwho I am.\n\n⸻\n\nVerse 2\n\nMy voice doesn’t have to\nsound like someone else,\nI can speak in my way,\nI can be myself.\n\nEvery word I’m finding,\nevery step I take—\nis part of my story,\npart of what I make.\n\n⸻\n\nBridge\n\nSome voices come fast,\nsome voices take time.\nSome voices are quiet—\nand still they shine.\n\n⸻\n\nFinal Chorus\n\nI am me—\nI belong.\nI have a voice—\nI am strong.\n\nSide by side,\nwe all show—\nwe are learning\nwho we are.\n\n⸻\n\nOutro (soft)\n\nJust like this…\nI begin."}, "bilingual": false, "cover": "covers/i-am-me.jpeg", "language": "English", "family": "0"}, {"id": 24, "title": "Aquí, aquí · Right Here, Right Here", "moment": "Begin", "audience": "Children", "blurb": "A 29-second bilingual transition.", "use": "Play as a cue to clean up and get ready for the next activity together. The steady drumbeat invites movement; aim to be ready for the quiet final “Ready?” and pause together before beginning. Used and loved by Tanya’s students at Lynwood.", "quote": "Aquí, aquí. Right here, right here.", "color": "teal", "variants": {"English + Español": "Respira y vuelve aquí…\nAquí, aquí.\nJuntos cambiamos ya.\nListos para empezar.\n\nBreathe and come back here…\nRight here, right here.\nNow we shift as one.\nReady to begin.\n\nReady?"}, "bilingual": true, "cover": "covers/aqui-aqui-right-here-illustrated.png", "language": "English + Español", "family": "24"}, {"id": 26, "title": "We Begin Here", "moment": "Begin", "audience": "All ages", "blurb": "A gentle welcome, with room to arrive just as you are.", "use": "Open a morning meeting, class, or gathering. Invite people to listen, watch, or join in at their own pace. Let “just as you are” welcome different ways of arriving, and use the final refrain to begin together.", "quote": "Some bring stories we may never know.", "color": "ochre", "variants": {"English": "Right here…\nwe begin here.\n\nWe begin here—\nbegin here… begin here…\n\nNot all at once—\n\njust as you are…\n\nStep by step—\nwe begin here.\n\n[Verse 1]\nSome come ready,\nSome arrive slow,\nSome bring stories\nWe may never know.\n\nYou don’t have to change\nTo belong right now—\nJust bring your whole self,\nWe’ll show you how.\n\n[Chorus ]\nWe begin here—\nbegin here…\nNot all at once—\njust as you are…\nBreath by breath—\nwe begin here.\n\n[Verse 2]\nSome will listen,\nSome will try,\nSome will watch\nBefore they reply.\n\nThere’s no one way\nTo step inside—\nEvery path\nIs welcome to arrive.\n\n[Bridge ]\nFeet on the ground…\nAir moving through…\nNothing to prove—\nJust becoming you…\n\n[Final Chorus ]\nWe begin here—\ntogether now…\nSide by side—\njust as we are…\nStep by step—\nwe begin here.\n\n[Outro ]\nWhenever we need…\nwe begin here."}, "bilingual": false, "cover": "covers/we-begin-here-illustrated.png", "language": "English", "family": "26"}, {"id": 1, "title": "Not Yet, Still Here", "moment": "Keep going", "audience": "All ages", "blurb": "A steady refrain for the tricky part of learning.", "use": "Invite listeners to join only the words “I’m still here.” Leave room to rest, breathe, and decide on a next small attempt.", "quote": "Not yet—I’m still here.", "color": "plum", "variants": {"English": "[Intro]\n\nNot yet…\nstill here…\n\n[Chorus]\n\nNot yet—\nI’m still here.\nNot done—\nI’m still here.\n\nTake a breath—\nI’m still here.\nTry again—\nI’m still here.\n\n[Verse 1]\n\nThis part’s tricky,\nI can feel—\nSomething wobbly,\nSomething real.\n\nI don’t have it—\nThat’s okay—\nI’m still in it,\nI can stay.\n\n[Chorus]\n\nNot yet—\nI’m still here.\nNot done—\nI’m still here.\n\nBreath by breath—\nI’m still here.\nStep by step—\nI’m still here.\n\n[Verse 2]\n\nSome go faster,\nSome go slow,\nSome just need\nMore time to know.\n\nI don’t have to\nGet it now—\nI can learn it,\nI know how.\n\n[Bridge]\n\nHands can rest…\nEyes can see…\nNothing’s wrong…\nWith being me…\n\n[Final Chorus]\n\nNot yet—\nwe’re still here.\nNot done—\nwe’re still here.\n\nSide by side—\nwe’re still here.\nWe can try—\nwe’re still here.\n\n[Outro]\n\nNot yet…\nstill here."}, "bilingual": false, "cover": "covers/not-yet-still-here-illustrated.jpg", "language": "English", "family": "1"}, {"id": 20, "title": "Aún No, Sigo Aquí", "moment": "Keep going", "audience": "All ages", "blurb": "Un estribillo para acompañar los momentos difíciles del aprendizaje.", "use": "Invita al grupo a cantar “sigo aquí”. Deja espacio para respirar, descansar e intentar otra vez.", "quote": "Paso a paso—sigo aquí.", "color": "plum", "variants": {"Español": "[Intro]\n\nAún no…\nsigo aquí…\n\n[Chorus]\n\nAún no—\nsigo aquí.\nNo es el final—\nsigo aquí.\n\nTomo aire—\nsigo aquí.\nIntento otra vez—\nsigo aquí.\n\n[Verse 1]\n\nEsta parte\nse siente así—\nun poco incierta,\npero estoy aquí.\n\nNo lo tengo—\nestá bien—\nsigo dentro,\npuedo sostener.\n[Chorus]\n\nAún no—\nsigo aquí.\nNo es el final—\nsigo aquí.\n\nPaso a paso—\nsigo aquí.\nPoco a poco—\nsigo aquí.\n\n[Verse 2]\n\nAlgunos vuelan,\notros van despacio,\nalgunos solo\nnecesitan espacio.\n\nNo hace falta\nllegar ya—\npuedo aprender,\nva a llegar.\n\n[Bridge]\n\nNo hay error…\nen ser así…\npuedo estar…\ny seguir aquí…\n\n[Final Chorus]\n\nAún no—\nseguimos aquí.\nNo es el final—\nseguimos aquí.\n\nLado a lado—\nseguimos aquí.\nPodemos intentar—\nseguimos aquí.\n\n[Outro]\n\nAún no… sigo aquí…\naún no… sigo aquí…\naún no… sigo aquí…\nsigo aquí…\n…sigo aquí…"}, "bilingual": false, "cover": "covers/aun-no-sigo-aqui.jpg", "language": "Español", "family": "1"}, {"id": 2, "title": "Mariposa", "moment": "Play & imagine", "audience": "All ages", "blurb": "An expansive bilingual song about courage, color, and becoming.", "use": "Make space to move. Invite each person to invent their own butterfly movement, then share a color or gesture that feels like them.", "quote": "Let your colors rise and flow.", "color": "ochre", "variants": {"English + Español": "There’s a whisper in your footsteps,\nA soft light in how you rise.\nEvery dream inside your ribcage\nKnows the rhythm of the skies.\n\nWhen the world begins to open,\nAnd your courage starts to shine,\nSpread your wings into becoming\n\nEvery moment is your time.\n\nMariposa—¡brillas así!\nLibre y radiante dentro de ti.\n\nAbre tus alas, déjate ir,\nNaciste fuerte para subir.\n\nHay un canto en tu camino,\nUna fuerza en tu latir,\nCuando el viento te susurra,\nSabes bien a dónde ir.\n\nMariposa—¡brillas así!\nLibre y radiante dentro de ti.\n\nCada paso, cada intento,\nVa contando tu sentir.\n\nButterfly—oh can’t you see?\nLight is blooming where your heart wants to be.\n\nLet your colors rise and flow,\nYou were made to lift and glow.\n\nMariposa!\nFly so free!\n\nMariposa!\nShine in me!\n\nBrilla, brilla!\nShine in me!\n\nSiente el viento…\nLet it rise…\n\nAbre alas…\nClaim the skies!\n\nWhen the mountains feel too heavy,\nAnd the world feels far and wide…\n\nRecuerda, niña mariposa,\nTu luz vive en cada paso que das.\n\nYour becoming is a sunrise—\nLet it warm you as you grow.\n\nCada sueño que te llama\nTe recuerda quién tú sos.\n\nMariposa—¡brillas así!\n\nMariposa—¡brillas así!\nButterfly, you’re rising free.\n\nLibre y radiante dentro de ti,\nEvery color finding who to be.\n\nAbre tus alas, déjate ir,\nLet your brave heart carry you higher.\n\nNaciste fuerte para subir,\nYou were born a dancing fire.\n\nHey-hey-ho… hoo-hey…\nSiente el viento… fly today…\nHey-hey-ho… hoo-hey…\nMariposa—find your way…"}, "bilingual": true, "cover": "covers/mariposa-bilingual.jpg", "language": "English + Español", "family": "2"}, {"id": 21, "title": "Mariposa", "moment": "Play & imagine", "audience": "All ages", "blurb": "Una celebración compartida: voces, generaciones y espacio para desplegar las alas.", "use": "Invita a cantar, moverse o escuchar. Cada persona puede participar a su manera y celebrar el vuelo de las demás.", "quote": "Abre tus alas, déjate ir.", "color": "ochre", "variants": {"Español": "Chispa fiel, luz pequeñita,\nYa despiertas… ya cerquita.\nCon tus alas al latir,\nSiente cómo vas a abrir.\n\nEscucha—\n¡ju-ju-hey!\nSiente—\n¡hey-hey-ho!\n\nMariposa—¡vuela al sol!\nGira en el aire con tu color.\nRíe con el viento, juega al volar,\nMuestra al mundo tu brillar.\n\nMariposa—¡brillas así!\nLibre y radiante dentro de ti.\nAbre tus alas, déjate ir,\nNaciste fuerte para subir.\n\nSalta al viento, toca la flor,\nNo eres pequeña—crece tu valor.\nCada giro, cada vaivén,\nDice al mundo: “Yo también.”\n\nEscucha—\n¡ju-ju-hey!\nSiente—\n¡hey-hey-ho!\n\nMariposa—¡vuela al sol!\nGira en el aire con tu color.\nRíe con el viento, juega al volar,\nHecha para cielo y mar.\n\nSube el cerro,\ncruza el río,\nabre alas\ncon tu brío.\n\nCada curva,\ncada acción,\nva diciendo\ntu canción.\n\nMariposa—vuela al sol,\nbrilla en tu propio resplandor.\nCada tono, cada latir,\ncuenta historias de tu sentir.\n\nMariposa—ríe al subir,\nlibre, salvaje, ¡sí, por ti!\nVuela alto, vuela feliz—\ntú naciste para ser así."}, "bilingual": false, "cover": "covers/mariposa-espanol.jpg", "language": "Español", "family": "2"}, {"id": 22, "title": "Mariposa", "moment": "Play & imagine", "audience": "All ages", "blurb": "A playful invitation to flutter, explore, and discover together.", "use": "Invite children and adults to move like butterflies. Make room for big movements, small gestures, and quiet watching.", "quote": "You were made to lift and rise!", "color": "ochre", "variants": {"English": "Little spark, little light,\nWaking up, taking flight,\nTiny wings by your side,\nFeel the flutter rise inside!\n\nListen—\nhoo-hoo-hey!\nFeel it—\nhey-hey-ho!\n\nMariposa—fly, little one,\nTwirl in the air, spin in the sun!\nLaugh with the breeze, dance with the sky,\nShow the world you’re ready to fly!\n\nMariposa—bright as can be,\nColors that shimmer wild and free!\nOpen your wings—let your heart try,\nYou were made to lift and rise!\n\nSkip the wind, hop the stone,\nYou’re not small—you’ve grown and grown!\nEvery flap, every glide,\nTells the world you’ve got your stride!\n\nHear it—\nhoo-hoo-hey!\nFeel it—\nhey-hey-ho!\n\nMariposa—fly, little one,\nTwirl in the air, spin in the sun!\nLaugh with the breeze, dance with the sky,\nYou were made for flying high!\n\nUp the hill,\n’Cross the stream,\nLift your wings—\nChase your dream.\n\nEvery swirl,\nEvery turn,\nTeaches you\nWhat you can learn.\n\nMariposa—fly, little one,\nShine in the light you’ve become!\nEvery color tells your story,\nEvery heartbeat sings your glory.\n\nMariposa—laugh as you rise,\nFill the air with your surprise!\nFlutter bright, so wild and free—\nYou’re exactly meant to be."}, "bilingual": false, "cover": "covers/mariposa-english.jpg", "language": "English", "family": "2"}, {"id": 3, "title": "Every Voice Belongs", "moment": "Belong", "audience": "All ages", "blurb": "An invitation to speak as you can—and be heard.", "use": "Echo the chorus together. Then invite a word, gesture, sign, or home-language greeting, with time to listen to each contribution.", "quote": "Speak how you can. We’re listening.", "color": "teal", "variants": {"English": "[Verse 1]\n\nSome of us speak softly,\nSome are learning how,\nSome carry many languages\nThey don’t always say out loud.\nEvery word has a story,\nEvery sound has a home,\nWe’re not here to get it perfect—\nWe’re here to be known.\n\n[Chorus]\n\nLeader: Every word is a doorway,\nAll: Every word is a doorway,\nLeader: Every voice belongs.\nAll: Every voice belongs.\n\nAll (together):\nEvery word is a doorway,\nEvery voice belongs.\n\n[Verse 2]\n\nIt’s not about the grammar,\nOr getting every sound just right,\nIt’s the courage it takes to try\nAnd let your meaning take its flight.\nWhen we listen for the message\nMore than how it’s said,\nWe build a bridge between us\nInstead of counting what’s ahead.\n\n[Chorus]\n\nEvery word is a doorway,\nEvery voice belongs.\nEvery word is a doorway,\nEvery voice belongs.\n\n[Bridge]\n\nSome words come fast,\nSome come slow.\nSome need time\nBefore they show.\nBut every voice is carrying\nMore than we can see—\nWhen you speak,\nYou’re reaching me.\n\n[Final Chorus]\n\nEvery word is a doorway,\nEvery voice belongs.\nEvery language, every learner,\nEvery right and wrong.\nWe don’t sort,\nWe don’t compare—\nWe meet each other there.\n\nEvery word is a doorway,\nEvery voice belongs.\n\n[Outro]\n\nSpeak how you can.\nWe’re listening."}, "bilingual": false, "cover": "covers/every-voice-belongs.jpg", "language": "English", "family": "3"}, {"id": 4, "title": "Many Ways Forward", "moment": "Keep going", "audience": "All ages", "blurb": "Different rhythms. Different approaches. Room for each.", "use": "Use the call-and-response chorus, then ask: What is one way you might approach this task? Make room for talking, drawing, building, or observing.", "quote": "Different rhythms—same shared time.", "color": "sage", "variants": {"English": "[Intro]\n\nHey—\nnot one way.\n\nMany ways.\n\n⸻\n\n[Verse 1]\n\nSome start fast—\nsome wait.\n\nSome jump in—\nsome hesitate.\n\nSome talk it out—\nsome move first.\n\nSome need quiet\nbefore the words.\n\n⸻\n\n[Pre-Chorus – lift]\n\nNo one path—\nno single line,\n\nDifferent rhythms—\nsame shared time.\n\n⸻\n\n[Chorus]\n\nLeader:\nMany ways forward!\n\nAll:\nMany ways!\n\nLeader:\nNot just one road—\n\nAll:\nNot just one way!\n\n⸻\n\nAll together:\n\nStep in, step through,\nhowever you do—\n\nMany ways forward,\nand they all count too.\n\n⸻\n\n[Verse 2]\n\nSome build slow—\nsome spark quick.\n\nSome stay steady—\nsome shift.\n\nSome get there\nby going around,\n\nSome find their way\nwithout a sound.\n\n⸻\n\n[Pre-Chorus]\n\nNot the same—\nand that’s the point,\n\nDifferent paths—\nbut still joined.\n\n⸻\n\n[Chorus]\n\nLeader:\nMany ways forward!\n\nAll:\nMany ways!\n\nLeader:\nCome as you are—\n\nAll:\nYou’re already on the way!\n\n⸻\n\nStep in, step through,\nhowever you do—\n\nMany ways forward,\nand they all count too.\n\n⸻\n\n[Bridge]\n\nTake your time.\nFind your pace.\n\nThere’s no rush—\nin this space.\n\nYou don’t have to\nmatch the sound—\n\nJust step in.\nYou’re already found.\n\n\n⸻\n\n[Final Chorus]\n\nLeader:\nMany ways forward!\n\nAll:\nMany ways!\n\nLeader:\nSide by side—\n\nAll:\nDifferent ways!\n\n⸻\n\nAll together:\n\nStep in, step through,\nhowever you do—\n\nMany ways forward,\nand they all count too.\n\n⸻\n\n[Outro]\n\nCome in how you are—\n\nWe’ll go from there."}, "bilingual": false, "cover": "covers/many-ways-forward.jpg", "language": "English", "family": "4"}, {"id": 23, "title": "Muchas Formas de Avanzar", "moment": "Keep going", "audience": "All ages", "blurb": "Diferentes ritmos y caminos. Hay lugar para cada persona.", "use": "Prueben el coro como llamada y respuesta. Después, compartan distintas maneras de abordar una tarea: hablar, dibujar, construir u observar.", "quote": "No hay una sola forma.", "color": "sage", "variants": {"Español": "[Intro]\n\nEy—\nno hay una sola forma.\n\nHay muchas.\n\n⸻\n\n[Verso 1]\n\nAlgunos van rápido—\notros esperan.\n\nAlgunos se lanzan—\notros lo piensan.\n\nAlgunos hablan—\notros actúan.\n\nAlgunos necesitan calma\nantes de la voz.\n\n⸻\n\n[Pre-Coro\n\nNo hay un camino—\nni una sola línea,\n\nRitmos distintos—\nmismo tiempo compartido.\n\n⸻\n\n[Coro]\n\nLíder:\n¡Muchas formas de avanzar!\n\nTodos:\n¡Muchas formas!\n\nLíder:\nNo es un solo camino—\n\nTodos:\n¡No es una sola forma!\n\n⸻\n\n[Todos juntos]\n\nDa un paso, sigue adelante,\na tu manera—\n\nMuchas formas de avanzar,\ny todas cuentan también.\n\n⸻\n\n[Verso 2]\n\nAlgunos construyen lento—\notros encienden rápido.\n\nAlgunos siguen firmes—\notros cambian.\n\nAlgunos llegan\ndando la vuelta,\n\nOtros encuentran su rumbo\nsin hacer ruido.\n\n⸻\n\n[Pre-Coro]\n\nNo es igual—\ny de eso se trata,\n\nCaminos distintos—\npero juntos avanzan.\n\n⸻\n\n[Coro]\n\nLíder:\n¡Muchas formas de avanzar!\n\nTodos:\n¡Muchas formas!\n\nLíder:\nVen como eres—\n\nTodos:\n¡Ya estás en camino!\n\n⸻\n\n[Todos juntos]\n\nDa un paso, sigue adelante,\na tu manera—\n\nMuchas formas de avanzar,\ny todas cuentan también.\n\n⸻\n\n[Puente]\n\nTómate tu tiempo.\nEncuentra tu paso.\n\nNo hay prisa\nen este espacio.\n\nNo tienes que\nsonar igual—\n\nSolo entra.\nYa perteneces.\n\n⸻\n\n[Coro Final]\n\nLíder:\n¡Muchas formas de avanzar!\n\nTodos:\n¡Muchas formas!\n\nLíder:\nLado a lado—\n\nTodos:\n¡Formas distintas!\n\n⸻\n\n[Todos juntos]\n\nDa un paso, sigue adelante,\na tu manera—\n\nMuchas formas de avanzar,\ny todas cuentan también.\n\n⸻\n\n[Outro]\n\nLlega como eres—\n\nSeguimos desde ahí."}, "bilingual": false, "cover": "covers/muchas-formas-de-avanzar.jpg", "language": "Español", "family": "4"}, {"id": 5, "title": "We Come Back", "moment": "Return to calm", "audience": "Children", "blurb": "A shared return, one breath and one moment at a time.", "use": "Offer the refrain after a busy moment. Invite feet to find the floor and allow each person to rejoin at their own pace.", "quote": "Some are ready now, some need more time.", "color": "teal", "variants": {"English": "Take a breath…\nwe come back\n\n[Chorus ]\n\nWe come back—\nWe come back.\nNot all at once—\nJust like that.\nBreath by breath—\nWe come back.\n\n[Verse 1]\n\nWhen the room gets loud\nAnd the rhythm slips,\nWhen the moment scatters\nFrom our fingertips—\n\nWe don’t rush to fix it,\nWe don’t push it through,\nWe find where we are…\nAnd begin from true.\n\n[Chorus ]\n\nWe come back—\nWe come back.\nNot all at once—\nJust like that.\nBreath by breath—\nWe come back.\n\n[Verse 2]\n\nSome are ready now,\nSome need more time,\nSome are finding quiet\nBefore they find a line.\n\nYou don’t have to hurry,\nYou don’t have to prove—\nComing back to center\nIs the strongest move.\n\n[Bridge]\n\nFeet on the floor…\nAir in the chest…\nNothing is broken—\nWe’re just finding rest.\n\n[Final Chorus]\n\nWe come back—\nWe come back.\nTogether now—\nJust like that.\nSide by side—\nWe come back.\n\n[Outro ]\n\nWhenever we need…\nWe come back."}, "bilingual": false, "cover": "covers/we-come-back-illustrated.jpg", "language": "English", "family": "5"}, {"id": 25, "title": "Volvemos", "moment": "Return to calm", "audience": "Children", "blurb": "Paso a paso. Poco a poco. A shared return to calm.", "use": "After a busy or scattered moment, invite the group to return together without rushing. One voice can offer “Volvemos” and the group can echo it. Let the bridge invite feet to the floor, a breath, and a moment of rest. The Spanish partner to We Come Back.", "quote": "No todo de una—poco a poco.", "color": "teal", "variants": {"Español": "Respira…\nvolvemos…\n\nVolvemos—\nVolvemos.\nNo todo de una—\npoco a poco.\nPaso a paso—\nvolvemos.\n\n[Verso 1]\nCuando el cuarto suena\ny el ritmo se va,\ncuando el momento\nse empieza a soltar—\n\nNo hay que apurarlo,\nno hay que forzar,\nvolvemos a donde\npodemos empezar.\n\n[Coro]\nVolvemos—\nvolvemos.\nNo todo de una—\npoco a poco.\nPaso a paso—\nvolvemos.\n\n[Verso 2]\nAlgunos ya listos,\notros van más lento,\nunos buscan calma\nantes del intento.\n\nNo hay que apurarse,\nno hay que probar,\nvolver al centro\nnos ayuda a estar.\n\n[Bridge]\nPies en el suelo…\naire al entrar…\nnada está roto…\nsolo es descansar…\n\n[Final Chorus]\nVolvemos—\nvolvemos.\nJuntos ahora—\npoco a poco.\nLado a lado—\nvolvemos.\n\n[Outro]\nRespira…\npaso a paso…\nvolvemos…"}, "bilingual": false, "cover": "covers/volvemos-illustrated.png", "language": "Español", "family": "5"}, {"id": 6, "title": "Breathe Me Back to Center", "moment": "Return to calm", "audience": "Teens & adults", "blurb": "An unhurried song for noticing and finding your ground.", "use": "Offer optional listening and a comfortable position. Afterwards, invite a word or a quiet moment; no one needs to explain what they felt.", "quote": "I can re-enter in my time.", "color": "plum", "variants": {"English": "[Verse 1]\nThere's a tremor in my shoulders,\nThere's a buzzing in my chest,\nWhen the world begins to scatter\nAnd the noise won't let me rest.\nBut I’ve learned the quiet language\nOf returning to my ground,\nIn the rhythm of my breathing\nWhere my center can be found.\n\n[Chorus]\nBreathe me back to center,\nBreathe me into still.\nLet the storm clouds in my ribcage\nFind a sky they can’t help fill.\nLet my feet remember safety,\nLet my heartbeat slow its climb—\nIn the cradle of my body\nI can re-enter in my time.\n\n[Verse 2]\nThere is wisdom in the shaking,\nThere is power in the pause,\nEvery tremble is a teacher,\nEvery exhale knows the cause.\nWhen the ground is gently waiting\nFor my spirit to return,\nI remember: regulation\nIs a practice that I learn.\n\n[Chorus]\nBreathe me back to center,\nBreathe me into still.\nLet the storm clouds in my ribcage\nFind a sky they can’t help fill.\nLet my feet remember safety,\nLet my heartbeat slow its climb—\nIn the cradle of my body\nI can re-enter in my time.\n\n[Bridge]\nWith every breath, I unravel\nThe chaos that resides,\nInhale the calm, exhale the battle,\nTrust in this gentle ride.\nI’ll take it slow, let me follow,\nThe whispers of my soul,\nAs I navigate this feeling,\nAnd reclaim what makes me whole.\n\n[Verse 3]\nSo when the tremors start to quake me,\nAnd the world feels far away,\nI will find my steady heartbeat\nIn the stillness of the day.\nWhen the longing pushes forward,\nAnd the clock begins to spin,\nI’ll breathe me back to center,\nAnd let my journey begin.\n\n[Chorus]\nBreathe me back to center,\nBreathe me into still.\nLet the storm clouds in my ribcage\nFind a sky they can’t help fill.\nLet my feet remember safety,\nLet my heartbeat slow its climb—\nIn the cradle of my body\nI can re-enter in my time.\n\n[Outro]\nWith every little moment,\nI’ll embrace what life bestows,\nThrough the tremors and the winter,\nIn my center, love still grows."}, "bilingual": false, "cover": "covers/breathe.jpeg", "language": "English", "family": "6"}, {"id": 7, "title": "Brighter Than Before", "moment": "Grow community", "audience": "All ages", "blurb": "Gardens, long tables, and the small acts that bring a place alive.", "use": "Invite listeners to picture one place they share. What small addition—a greeting, a garden, a gathering—could help it feel more alive?", "quote": "Little by little. Block by block.", "color": "ochre", "variants": {"English": "Verse 1\n\nChalk dusted fingertips\nSunlight bouncing off the spokes\nTomatoes climbing chain-link fences\nMurals peppering the roads\n\nSomeone tuning up a guitar\nAt the table by the trees\nAnother sketching bigger futures\nOn the back of grocery receipts\n\nAnd the old men by the garden\nLaugh like they have seen this bloom\nEvery small thing leaning upward\nLike the whole street found more room\n\n⸻\n\nPre-Chorus\n\nWhat if\n\nThe places that we share\nCould grow more alive than ever?\n\nWhat if\n\nOrdinary days held\nMore color than survival?\n\n⸻\n\nChorus\n\nBecause\n\nHope grows brighter when it’s carried\nAnd joy moves farther hand to hand\n\nThen\n\nEmpty corners turn to gathering places\nBuilt up by greeting and delight\n\nBecause\n\nPeople shine in different weather\nWhen every voice has room to ring\n\nNow\n\nLook what becomes possible\nWhen a whole town learns to wake big dreams\n\n⸻\n\nVerse 2\n\nLanterns swinging from the market\nPaint beneath the fingernails\nTeenagers leading younger children\nThrough the stories on the rails\n\nSomeone teaching bread and language\nSomeone teaching how to weld\nSomeone planting little orchards\nWhere abandoned concrete held\n\nAnd the woman at the corner\nHands out seedlings wrapped in news\nSays, “Nothing living stays small forever\nOnce enough hands help it through”\n\n⸻\n\nPre-Chorus\n\nWhat if\n\nBelonging felt as natural\nAs sitting in the evening light?\n\nWhat if\n\nPeople lingered long enough\nTo help a whole place come alive?\n\n⸻\n\nChorus\n\nBecause\n\nBeauty grows where it is practiced\nAnd streets remember how to sing\n\nThen\n\nSidewalks bloom with invitation\nWindows open into spring\n\nBecause\n\nYoung hearts carry wild imagination\nAnd older hands remember how\n\nThen\n\nLittle by little\nBlock by block\nSomething brighter starts becoming now\n\n⸻\n\nBridge\n\nNot someday\nNot perfect\nNot after everything is fixed\n\nJust one mural\nOne garden\nOne long table in the sun\n\nAnd another\nAnd another\n\nUntil the air itself feels different\n\nLike a tide turning quietly\nLike a wave no one can stop\nRolling farther than expected\n’Til the dreams begin to wake\n\n⸻\n\nFinal Chorus\n\nBecause\n\nHope grows stronger when it’s shared\nAnd stories travel farther than fear\n\nThen\n\nNeighborhoods become living canvases\nAnd strangers turn familiar here\n\n⸻\n\nOutro\n\nMorning light on open doorways\nPaint and jasmine in the breeze\nEvery small thing leaning upward\nLike the whole street learned to breathe"}, "bilingual": false, "cover": "covers/brighter-than-before-illustrated.jpg", "language": "English", "family": "7"}, {"id": 8, "title": "Pass It On", "moment": "Grow community", "audience": "All ages", "blurb": "The languages we carry, and the people we carry them toward.", "use": "Invite a family phrase, saying, sign, or song someone would like to carry forward. Sharing a personal story is always optional.", "quote": "It’s lullabies and market calls.", "color": "coral", "variants": {"English": "[Verse 1]\nYou hold a world inside your voice,\nA story shaped by sound and choice.\nEach word you speak, each phrase you say,\nIs a gift you carry every day.\nDon’t keep it hidden, don’t let it fade—\nThat language love your elders made.\n\n[Chorus]\nPass it on, pass it strong—\nEvery language, every song.\nTo your children, to your friends,\nLet the river never end,\nLet the river never end.\n\n[Verse 2]\nPower lives in every tongue,\nOld and wise or just begun.\nTeach the words that made you you,\nSo the world can learn them too.\nIt’s more than grammar, more than sound,\nIt's roots and wings on sacred ground.\n\n[Chorus]\nPass it on, pass it strong—\nEvery language, every song.\nTo your children, to your friends,\nLet the river never end,\nLet the river never end.\n\n[Bridge]\nIt’s lullabies and market calls,\nIt’s kitchen talk and classroom halls.\nEach language spoken, signed, or sung,\nIs the bridge from old to young.\nA legacy not in a book,\nBut in every glance and every look.\n\n[Chorus]\nPass it on, pass it true—\nSomeone’s future lives in you.\nIn your whisper, shout, or song,\nKeep the living language strong.\n\n[Verse 3]\nNot just words, but ways to see—\nA map of hearts and history.\nSome accents thick, some light and free,\nEvery tone’s a melody.\nWith every lesson, with every rhyme,\nWe weave the fabric, a thread through time.\n\n[Chorus]\nPass it on, pass it strong—\nEvery language, every song.\nTo your children, to your friends,\nLet the river never end,\nLet the river never end.\n\n[Outro]\nSo raise your voice, let it be known,\nIn every heart, a seed is sown.\nTogether we'll shine, our stories spun,\nIn every accent, we are one."}, "bilingual": false, "cover": "covers/pass-it-on.jpg", "language": "English", "family": "8"}, {"id": 9, "title": "Echo of My Name", "moment": "Belong", "audience": "Children", "blurb": "Names as stories, rhythms, and invitations to know each other.", "use": "Invite people to say a name they want to be called, and ask permission for the group to echo it. A chosen name or invented rhythm is welcome.", "quote": "A world in a sound.", "color": "sage", "variants": {"English + Español": "[Verse 1]\nI carry a name that was given with care,\nWhispered by someone who wanted me there.\nA word full of love, a world in a sound—\nMy name holds a story that’s always around.\n\n[Chorus]\nEcho, echo… of my name,\nIt’s more than letters, it’s more than fame.\nEcho, echo… across time and space,\nIt brings me home, it finds my place.\n\n[Verse 2]\nMi nombre es un río, viene de atrás,\nCorre con fuerza, no se detendrá.\nMy name is a river, ancient and wide—\nFlowing through voices on every side.\n\n[Chorus]\nEcho (echo!) of my name (my name!),\nGiven with hope (with hope!) never the same (the same!)\nEcho (echo!) when I speak (I speak!),\nMy name is power, bold and unique!\n\n[Bridge]\nSay it loud: Amara!\nSay it proud: Mateo!\nThis is me: Leilani!\nFamily tree: João!\nWhispers grow: Amina!\nStories show: Haruto!\nHere I stan: Together we shine!\n\n[Outro]\nEcho, echo… in joyful refrain,\nEvery name we carry, let’s honor the gain.\nEcho, echo… a joyful embrace,\nIn the world of our names, we’re finding our place."}, "bilingual": true, "cover": "covers/echo-of-my-name.jpg", "language": "English + Español", "family": "9"}, {"id": 10, "title": "The Language Dance", "moment": "Play & imagine", "audience": "Children", "blurb": "Hop on a syllable. Slide down a sound. Let words move.", "use": "Choose a word or phrase and create a gesture for its sound. Let learners teach one another their movements.", "quote": "She’d gather new phrases and launch them like kites!", "color": "coral", "variants": {"English": "[Verse 1]\nIn a town on a hill where the wild breezes blow,\nLived a kid who could speak in a language or so.\nShe’d whisper in Spanish, then dance into French,\nWith a laugh in Swahili, she’d leap off the bench!\n\n[Chorus]\nWords can fly, and twist, and spin—\nFrom every place you’ve ever been!\nBig or small, or short or long,\nEvery voice deserves a song!\n\n[Verse 2]\nA swirl from the desert, a rhyme from the sea,\nA sentence that sings from a red maple tree.\nFrom Arabic greetings to Tagalog delight,\nShe’d gather new phrases and launch them like kites!\n\n[Chorus]\nWords can fly, and twist, and spin—\nFrom every place you’ve ever been!\nLoud or soft, or bright or deep,\nSome are funny, some make you weep!\n\n[Bridge]\nSo hop on a syllable, slide down a sound,\nRide on a rhyme where the verbs bounce around!\nLanguage is magic—it opens the door,\nTo friends you’ve not met and to tales never told before.\n\n[Chorus]\nWords can fly, and twist, and spin—\nFrom every heart and every grin!\nShout them high or hum them low,\nLet the power of language grow!\n\n[Verse 3]\nIn the sun-drenched afternoons, she would sing with the birds,\nWith a hop, skip, and a jump, she’d dance with her words.\nFrom cultures around, she painted the air,\nWith stories unspoken, she’d wish you were there!\n\n[Refrain]\nWords can fly, and twist, and spin—\nFrom every place you’ve ever been!\nBig or small, or short or long,\nEvery voice deserves a song!\n\n[Outro]\nSo join in the laughter, the joy in the sound,\nIn this magical town, where our dreams are unbound.\nEvery language a treasure, every tongue a delight,\nLet’s celebrate together, dance into the night!"}, "bilingual": false, "cover": "covers/the-language-dance.jpg", "language": "English", "family": "10"}, {"id": 11, "title": "Language Power", "moment": "Play & imagine", "audience": "Children", "blurb": "Whispers, giggles, greetings, and words with somewhere to go.", "use": "Play with the same greeting as a whisper, a rhythm, a gesture, or a chorus. Invite languages the group knows.", "quote": "Our stories wear sneakers.", "color": "ochre", "variants": {"English": "(Verse 1)\n\nI speak with a whistle, a whisper, a cheer—\nA giggle, a jiggle, a “hi” and “I’m here!”\nFrom rooftops in Rio to sidewalks in Spain,\nOur words ride the wind like a colorful train.\n\nThey bounce through the trees, they skip through the air,\nThey tangle with tumbleweeds, swirl through your hair!\nSay “hola” or “hi,” or just wiggle your shoe—\nThe power of language is waiting for YOU!\n\n(Chorus)\n\nLanguage power! Let it play!\nIt zings and it zaps in a wiggly way!\nIt skips over borders, it zooms through the sky,\nIt dances in dreams and it never asks why.\n\nSay “hello,” say “salām,”\nsay “jambo” or “nǐ hǎo”—\nEach word brings a smile\nthat lights up the day now!\n\nFrom giggles to greetings, from whispers to shouts,\nLanguage is magic inside and out!\n\n(Verse 2)\n\nFrom mountaintop whispers to oceans that sing,\nEach dialect dances, each word has a wing!\nA swirl from the desert, a skip through the snow,\nWherever we wander, our voices can go.\n\nOur stories wear sneakers, they hop and they glide,\nWith laughter and rhythm, they bounce side to side.\nSo whether you speak with a click or a cheer,\nYour language has power—it’s welcome right here!\n\n(Final Chorus)\n\nLanguage power—loud and clear!\nFrom every heart, a voice we hear.\nWhether it whispers or bounces or sings,\nEvery word has magical wings!\n\nSo wave your words, let stories soar—\nLanguage connects us and opens the door.\nIn every tongue, in every tone,\nOur words can travel on their own"}, "bilingual": false, "cover": "covers/language-power.jpg", "language": "English", "family": "11"}, {"id": 12, "title": "Learning’s Journey", "moment": "Keep going", "audience": "All ages", "blurb": "A song for returning to something with new eyes.", "use": "After revisiting a task, ask: What do you bring this time that you didn’t bring before? A drawing or one sentence is enough.", "quote": "Every time we come back, we bring something we didn’t know.", "color": "sage", "variants": {"English": "[Verse 1]\n\nSometimes the path bends backward,\nSometimes it feels unclear,\nWe thought we’d left this lesson\nBut it’s meeting us right here.\nIt’s not the end of knowing,\nIt’s not a step we missed,\nIt’s the way understanding\nLearns how to exist.\n\n[Chorus]\n\nWe circle, we wander, we try again,\nThat’s how learning grows.\nWe pause, we return, we begin again,\nMore than we ever know.\nIt’s not falling behind,\nIt’s finding our way—\nWe circle, we wander,\nAnd learning stays.\n\n[Verse 2]\n\nThere’s courage in repeating,\nThere’s wisdom in the slow,\nEvery time we come back\nWe bring something we didn’t know.\nWhat felt like starting over\nIs deeper than before,\nThe path looks new each time\nBecause we’re not the same as before.\n\n[Chorus]\n\nWe circle, we wander, we try again,\nThat’s how learning grows.\nWe pause, we return, we begin again,\nMore than we ever know.\nIt’s not falling behind,\nIt’s finding our way—\nWe circle, we wander,\nAnd learning stays.\n\n[Bridge (spoken or gently sung)]\n\nThe spiral isn’t a mistake.\nIt’s how depth is made.\nEvery return brings meaning\nThat couldn’t come the first time.\n\n[Final Chorus (soft lift, then resolve)]\n\nWe circle, we wander, we try again,\nThat’s how learning grows.\nWith every return, we see more clearly\nThan we did before.\nStep by step,\nDay by day—\nWe circle, we wander,\nAnd learning stays.\n\n[Outro (almost whispered)]\n\nGoing back\nIs how we go forward."}, "bilingual": false, "cover": "covers/learnings-journey-illustrated.jpg", "language": "English", "family": "12"}, {"id": 13, "title": "Joy Stays", "moment": "Reflect & teach", "audience": "Educators", "blurb": "A reminder to make room for wonder inside the learning.", "use": "Recall a moment of joy that helped someone participate. Choose one small way to invite that quality into your next lesson.", "quote": "Joy isn’t a reward. It’s the door.", "color": "ochre", "variants": {"English": "[Verse 1]\n\nWe don’t start with all the answers,\nWe don’t rush to get it right,\nWe begin with something simple—\nA spark, a laugh, a bit of light.\nWhen the room feels safe and open,\nWhen our shoulders drop their load,\nLearning finds a place to land\nInstead of feeling owed.\n\n[Chorus]\n\nWhen we laugh, we listen better,\nWhen we smile, we stay.\nJoy isn’t extra,\nIt’s how learning finds its way.\nWe don’t force it,\nWe don’t stray—\nJoy walks in,\nAnd learning stays.\n\n[Verse 2]\n\nIt’s the song before the lesson,\nIt’s the wonder in the room,\nIt’s the moment someone realizes\n“I can do this too.”\nNot a break from what we’re teaching,\nNot a prize we give away,\nJoy is how the brain remembers\nWhat it met along the way.\n\n[Chorus]\n\nWhen we laugh, we listen better,\nWhen we smile, we stay.\nJoy isn’t extra,\nIt’s how learning finds its way.\nWe don’t force it,\nWe don’t stray—\nJoy walks in,\nAnd learning stays.\n\n[Bridge (spoken or sung softly)]\n\nJoy doesn’t mean it’s easy.\nJoy doesn’t mean it’s small.\nIt means we found a way to learn\nWithout losing ourselves at all.\n\n[Final Chorus (gentle lift)]\n\nWhen we laugh, we listen better,\nWhen we smile, we stay.\nJoy isn’t extra,\nIt’s how learning finds its way.\nSide by side,\nDay by day—\nJoy comes first,\nAnd learning stays.\n\n[Outro (spoken, optional)]\n\nJoy isn’t a reward.\nIt’s the door."}, "bilingual": false, "cover": "covers/joy-stays-illustrated.jpg", "language": "English", "family": "13"}, {"id": 14, "title": "Before You Ask Them to Learn", "moment": "Reflect & teach", "audience": "Educators", "blurb": "Notice the stories that arrive before the lesson begins.", "use": "Listen before planning or a team conversation. Ask: What might learners be carrying, and what can we adjust in how we welcome them?", "quote": "Every child walks in holding more than they’re ready to show.", "color": "teal", "variants": {"English": "[Verse 1]\n\nBefore you ask them to listen,\nNotice how they arrived—\nWith echoes in their footsteps\nFrom other days, other lives.\nSome carry unfinished stories,\nSome carry light from before,\nEvery child walks in holding\nMore than they’re ready to show.\n\n[Pre-Chorus]\n\nLearning doesn’t start in the moment,\nIt starts where memory meets now.\nIt starts when the room feels safe enough\nTo let the body slow down.\n\n[Chorus]\n\nYou don’t teach by pushing harder,\nYou don’t pull them into line.\nYou shape the feeling of the moment\nSo learning can cross time.\nBefore you ask them to reach,\nBefore you ask them to try—\nYou build a space that can hold\nWho they’ve been\nAnd who they might become\nAt the same time.\n\n[Verse 2]\n\nSome kids learned early to hurry,\nSome learned early to hide.\nSome learned the world was watching,\nSome learned to shrink inside.\nBut when the tone feels welcoming,\nWhen the air feels kind,\nSomething softens in the present\nAnd opens a door behind.\n\n[Pre-Chorus]\n\nEmotion isn’t extra—\nIt’s how the brain decides\nWhether this moment is worth keeping,\nWhether it belongs in a life.\n\n[Chorus]\n\nYou don’t teach by pushing harder,\nYou don’t pull them into line.\nYou tend the feeling in the room\nSo growth can take its time.\nBefore you ask them to reach,\nBefore you ask them to try—\nYou make a place that can carry\nTheir yesterdays\nAnd their tomorrow’s why.\n\n[Bridge]\n\nEvery learner is a bridge\nBetween what was and what could be.\nIf the ground beneath them trembles,\nThe future waits patiently.\nTeaching isn’t speeding them forward—\nIt’s steadying the span\nSo when they step,\nThe next version of themselves\nCan land.\n\n[Final Chorus]\n\nYou don’t teach alone,\nYou teach with the field—\nWith the stories in the room,\nWith how the moment feels.\nLearning doesn’t rush,\nIt listens, it stays.\nWhen the space can hold the past\nThe future finds its invited to stay.\nYou teach by building the place\nWhere learning can finally say:\nOkay.\n\n[Outro]\n\nTeach the feeling.\nLearning will remember."}, "bilingual": false, "cover": "covers/before-you-ask-them-to-learn-illustrated.jpg", "language": "English", "family": "14"}, {"id": 15, "title": "Learning What Holds", "moment": "Reflect & teach", "audience": "Teens & adults", "blurb": "A reflection on the support that helps something take root.", "use": "Think of a change you want to sustain. Name one condition or relationship that could help hold it over time.", "quote": "It’s what holds when you do.", "color": "plum", "variants": {"English": "[Verse 1]\n\nSome things shine for a moment,\nLike a spark in the rain,\nThey feel bright when they happen,\nThen they fade just the same.\nWe call it a failure,\nWe call it a loss,\nBut nothing was broken—\nIt just didn’t have a place to rest long enough to become.\n\n[Pre-Chorus]\n\nNot every seed was meant to bloom on bare stone,\nNot every truth can stand alone.\n\n[Chorus]\n\nIt’s not what you reach for,\nIt’s what holds when you do.\nIt’s not how hard you try—\nIt’s the ground under you.\nSome things don’t stay\nBecause they weren’t meant to yet.\nIt’s not falling apart—\nIt’s learning what holds.\n\n[Verse 2]\n\nSome people look steady\nBecause something stayed,\nBecause someone stood with them\nWhile the shaking passed through their frame.\nOthers keep starting again,\nNot because they forgot,\nBut because what they’re carrying\nStill needs a place strong enough not to drop.\n\n[Pre-Chorus]\n\nGrowth isn’t louder when it’s real,\nIt’s quieter—\nBecause it finally feels safe to be still.\n\n[Chorus]\n\nIt’s not what you reach for,\nIt’s what holds when you do.\nIt’s not how hard you try—\nIt’s the ground under you.\nSome things don’t stay\nBecause they weren’t meant to yet.\nIt’s not falling apart—\nIt’s learning what holds.\n\n[Bridge]\n\nIf it didn’t last,\nIt doesn’t mean it was wrong.\nIt means the space around it\nWasn’t ready to keep it yet.\nNothing is lost—\nIt’s waiting for the right place to land.\n\n[Final Chorus]\n\nIt’s not the speed of the journey,\nOr the shape of the road,\nIt’s whether the moment\nHad somewhere to go.\nSome things return\nUntil the world can say “stay.”\nIt’s not starting over—\nIt’s finding the place\nWhere learning stays.\n\n[Outro]\n\nWhat lasts\nIs what’s held."}, "bilingual": false, "cover": "covers/learning-holds.jpeg", "language": "English", "family": "15"}, {"id": 16, "title": "The Space to Learn", "moment": "Reflect & teach", "audience": "Educators", "blurb": "The almost-raised hand. The pause that makes room for thinking.", "use": "Recall a time you waited rather than filling a silence. What did that make possible? Choose one place to leave more thinking time.", "quote": "Till the thinking lifts its head.", "color": "sage", "variants": {"English": "You don’t have to raise your voice\nFor the room to hear you breathe,\nThere’s a way a class goes quiet\nWhen it feels safe to be seen.\nIt’s not the rule on the wall,\nOr the chart that keeps the day—\nIt’s the space you make for thinking\nBefore you ask them what to say.\n\n[Pre-Chorus]\nEvery student brings a storm,\nEvery teacher brings a tone,\nWhat they learn before the lesson\nIs how it feels to not be alone.\n\n[Chorus]\nIt’s not power over people,\nIt’s the steadiness you bring,\nIt’s how learning starts unfolding\nWhen you don’t force anything.\nYou don’t push them toward the answer,\nYou don’t pull them into line—\nYou hold the room just long enough\nFor the courage to arrive.\n\n[Verse 2]\nThere’s a child who tests the edges,\nThere’s a silence in the back,\nThere’s a hand that almost rises\nThen decides to hold it back.\nYou don’t rush to fill the moment,\nYou don’t name what isn’t said,\nYou let the question linger\nTill the thinking lifts its head.\n\n[Pre-Chorus]\nWhat they carry walks in early,\nBefore the bell, before the book,\nAnd the first thing that they’re learning\nIs how it feels when someone looks.\n\n[Chorus]\nIt’s not power over people,\nIt’s the steadiness you bring,\nIt’s how learning starts unfolding\nWhen you don’t force anything.\nYou don’t push them toward the answer,\nYou don’t pull them into line—\nYou hold the room just long enough\nFor the courage to arrive.\n\n[Bridge]\nYou don’t need another program,\nYou don’t need a louder plan,\nThere’s a skill you’re already using\nWhen you pause instead of command.\nThat moment changes outcomes,\nMore than data ever shows—\nWhen a nervous system settles,\nThat’s when real attention grows.\n\n[Final Chorus (soft, then lift)]\nIt’s not power over people,\nIt’s the way you help them stand,\nIt’s the trust that makes a classroom\nMore than desks and more than plans.\nYou don’t carry all the answers,\nYou don’t have to be the guide—\nYou stay present, you stay human,\nAnd the learning opens wide.\n\n[Outro (almost spoken)]\nYou’re not doing less.\nYou’re doing it differently.\nAnd it’s working—\nEven when no one’s measuring it yet."}, "bilingual": false, "cover": "covers/the-space-to-learn-illustrated.jpg", "language": "English", "family": "16"}, {"id": 17, "title": "Find Our Voice", "moment": "Belong", "audience": "Teens & adults", "blurb": "Language, identity, and the right to carry your own voice.", "use": "Invite listeners to choose a line they connect with—or question. Offer space to write their own line about voice and identity.", "quote": "It’s a gift that we share, not a gap to erase.", "color": "plum", "variants": {"English": "[Intro]\n(Yeah, yeah)\nSteel pans play, hear the rhythm arise,\nTeen hearts beating, reaching for the skies.\n\n[Verse 1]\nThey told us to find our voice, but we got plenty to share,\nEach word a rhythm, a story laid bare.\nRoots in our journeys, the lines that entwine,\nA grandma’s song, a friend’s playful rhyme.\nIn the kitchen, she’s singing, spices fill the air,\nArabic jokes flow, laughter everywhere.\nFrom the text messages sent in the dead of the night,\nTo the codes that we write, we’re bringing the light.\n\n[Chorus]\nThis is our voice—don’t lower it,\nThis is our name—don’t change it.\nEmpowered and proud, we’re claiming our space,\nEvery language we carry, we own it with grace.\n\n[Verse 2]\nThe world tries to box us; they call it an accent,\nBut we shout “that’s echo!,” a legacy dense.\nGenerations of stories redefining the game,\nLanguage is power, we’ll never be tamed.\nIt’s a gift that we share, not a gap to erase,\nEvery word that we speak creates a new space.\nDreams in Spanish, Tagalog they weave,\nIn Vietnamese or ASL, we inspire and believe.\n\n[Chorus]\nThis is our voice—don’t lower it,\nThis is our name—don’t change it.\nEmpowered and proud, we’re claiming our space,\nEvery language we carry, we own it with grace.\n\n[Bridge]\nSome learn through poetry, some teach with a beat,\nNavigating this world, we’ll never face defeat.\nCode-switching our language, it’s just how we roll,\nIn their eyes, we’re different, but we’re still whole.\nWe are the tales that refuse to fit forms,\nRising through the noise, we’re breaking the norms.\n\n[Verse 3]\nWatch us rewrite the narrative, shape the new day,\nWith steel pans and beats, we’re paving the way.\nFeel the rhythm in our hearts, can’t hold back this fire,\nTogether we stand; our voices climb higher.\nNo shushing our brilliance; we stand tall and proud,\nEvery word is a weapon, and we’re singing out loud.\n\n[Chorus]\nThis is our voice—don’t lower it,\nThis is our name—don’t change it.\nEmpowered and proud, we’re claiming our space,\nEvery language we carry, we own it with grace.\n\n[Outro]\nSo let the steel pans ring, let the world hear our sound,\nWe speak in layers of culture, together we’re bound.\nWe’re the echoes of history, the dreams of today,\nEvery word that we speak will forever convey.\nWe find our voices, we rise and we sing—\nPowerful, vibrant, we’re everything."}, "bilingual": false, "cover": "covers/find-our-voice.jpg", "language": "English", "family": "17"}, {"id": 18, "title": "Belonging Is the Compass", "moment": "Grow community", "audience": "Teens & adults", "blurb": "A reflection on connection and where we feel whole.", "use": "Notice a place or relationship where you feel you can contribute as yourself. What draws you toward it?", "quote": "Belonging is the compass, a quiet steady pull.", "color": "teal", "variants": {"English": "[Verse 1]\nThere’s a softness in the shifting,\nWhen the road begins to change,\nI’ve been gathering my courage,\nFor the chapters still unnamed.\nWith each turn I find the rhythm,\nA dance I didn't know,\nEvery twist, it feels like freedom,\nAs I learn just where to go.\n\n[Verse 2]\nEvery step has shaped my being,\nEvery voice has helped me grow,\nNow I listen for the calling,\nWhere my gifts are meant to go.\nIn the laughter and the heartache,\nI find beauty in the scars,\nEvery moment’s like an anchor,\nGuiding me towards the stars.\n\n[Chorus]\nBelonging is the compass,\nA quiet steady pull,\nIt leads me toward connection,\nTo the places I feel whole.\nBelonging is the compass,\nA whisper on the breeze,\nI’m walking toward a future,\nThat’s already calling me.\n\n[Verse 3]\nWith the sun upon my shoulders,\nAnd the night within my heart,\nI embrace the journey onward,\nEvery ending is a start.\nThere’s a comfort in the knowing,\nThat I’m never on my own,\nWith each person that I cherish,\nI’m reminded I have grown.\n\n[Chorus]\nBelonging is the compass,\nA gentle guide in hand,\nIt brings me close to my dreamscape,\nTo the places where I stand.\nBelonging is the compass,\nA melody so sweet,\nNotes of love are softly playing,\nAs we gather at our feet.\n\n[Bridge — gentle hope]\nHeart open in the in-between,\nTrusting what my eyes can’t see,\nEvery ending plants a seed,\nLove will grow what’s meant to be.\nIn the stillness of the moments,\nIn the chaos, in the calm,\nI will find my way through shadows,\nWith the light of who I am.\n\n[Chorus — soft reprise]\nBelonging is the compass,\n(hush on final C)\nWith every breath, I find my way,\nThrough all the roads I’ve wandered stray.\nBelonging is the compass,\nIt's the journey of the heart,\nTogether we’ll embrace the dawn,\nAs we find our way, not far apart."}, "bilingual": false, "cover": "covers/belonging-is-the-compass-illustrated.jpg", "language": "English", "family": "18"}, {"id": 19, "title": "Finding Our Way", "moment": "Keep going", "audience": "Teens & adults", "blurb": "For the days when everyone else seems to have the map.", "use": "Ask which image feels familiar. Invite a reflection on what comparison makes harder, and what helps you find your own next step.", "quote": "Different streets, same town.", "color": "coral", "variants": {"English": "[Verse 1]\nEveryone’s walking like they know the way,\nPhones in their hands, eyes straight ahead.\nSomeone’s always louder, someone’s always late,\nSomeone looks like they already won the day.\n\nYou check the clock, then check your face,\nWonder if you missed some kind of race.\nBut no one handed out a map—\nThey just started walking and didn’t look back.\n\n[Chorus]\nWe move fast, we move slow,\nSome take off, some stay low.\nDifferent streets, same town,\nDifferent moments coming around.\n\n[Verse 2]\nSome people talk like they’re already there,\nLike confidence is something you wear.\nSome people try things ten times wrong,\nSome disappear and come back strong.\n\nIt looks messy up close,\nIt always does.\nBut growing’s not clean,\nAnd neither is love.\n\n[Chorus]\nWe move fast, we move slow,\nSome take off, some stay low.\nDifferent streets, same town,\nDifferent moments coming around.\n\n⸻\n\n[Bridge]\n\nNo one’s ahead of you.\nThey’re just somewhere else.\n\nNo one’s behind you either.\nYou’re exactly where you fell.\n\n⸻\n\n[Final Chorus]\nWe move fast, we move slow,\nSome take off, some stay low.\nDifferent streets, same town,\nDifferent moments coming around.\n\n[Outro]\nSomewhere else…\nIs still part of the way."}, "bilingual": false, "cover": "covers/finding-our-way-everyday.jpg", "language": "English", "family": "19"}];
